public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File parameter cannot be null.");
    }
    Deque<File> toProcess = new ArrayDeque<>();
    Deque<File> deleteOrder = new ArrayDeque<>();

    toProcess.push(file);
    try {
        // Build the deletion order (post‑order traversal)
        while (!toProcess.isEmpty()) {
            File current = toProcess.pop();
            deleteOrder.push(current);
            if (current.isDirectory()) {
                File[] children = current.listFiles();
                if (children != null) {
                    for (File child : children) {
                        toProcess.push(child);
                    }
                }
            }
        }

        // Register all files/directories in delete‑on‑exit order
        while (!deleteOrder.isEmpty()) {
            deleteOrder.pop().deleteOnExit();
        }
    } catch (SecurityException e) {
        throw new IOException("Failed to schedule deletion of " + file, e);
    }
}

