public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File must not be null");
    }
    if (!file.exists()) {
        throw new IOException("File does not exist: " + file);
    }
    // Post‑order traversal: children first, then the directory itself
    Deque<File> stack = new ArrayDeque<>();
    stack.push(file);
    while (!stack.isEmpty()) {
        File current = stack.peek();
        if (current.isDirectory()) {
            File[] files = current.listFiles();
            if (files != null && files.length > 0) {
                // Recurse into children before marking the directory itself
                for (File child : files) {
                    stack.push(child);
                }
                continue;
            }
        }
        // No more children to process; schedule deletion
        stack.pop();
        try {
            current.deleteOnExit();
        } catch (Exception e) { // deleteOnExit never throws IOException, but just in case
            throw new IOException("Failed to schedule deletion of: " + current, e);
        }
    }
}

