private static boolean isParameterSeparator(final char c){
    // Whitespace characters
    if (Character.isWhitespace(c)) {
        return true;
    }
    // Common delimiters that may separate parameters
    switch (c) {
        case ',':
        case ';':
        case '|':
        case ':':
        case '(':
        case ')':
        case '[':
        case ']':
        case '{':
        case '}':
            return true;
        default:
            return false;
    }
}

