private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null) {
        throw new IllegalArgumentException("list cannot be null");
    }
    if (list == this) {
        // Moving to itself is a no-op
        return;
    }
    // If the source list is empty, nothing to do
    if (list.head == null) {
        return;
    }

    // Attach the source list to this list
    if (this.head == null) {
        // Destination list is empty; simply adopt the source list
        this.head = list.head;
        this.tail = list.tail;
    } else {
        // Destination list is non-empty; link the two lists
        this.tail.next = list.head;
        list.head.prev = this.tail;
        this.tail = list.tail;
    }

    // Update the element counts
    this.size += list.size;

    // Clear the source list
    list.head = null;
    list.tail = null;
    list.size = 0;
}

