public void generateGraph(Graph<V,E> target, Map<String,V> resultMap){
    try{
        if(target == null || resultMap == null){
            return;
        }
        // Add all vertices from the resultMap to the graph
        for(Map.Entry<String,V> entry : resultMap.entrySet()){
            V v = entry.getValue();
            if(v != null && !target.containsVertex(v)){
                target.addVertex(v);
            }
        }
        int total = resultMap.size();
        if(total <= 1){
            return; // nothing to connect
        }
        int mid = total / 2;
        List<V> partA = new ArrayList<>(mid);
        List<V> partB = new ArrayList<>(total - mid);
        int idx = 0;
        for(Map.Entry<String,V> entry : resultMap.entrySet()){
            V v = entry.getValue();
            if(v == null){
