        // Connect every vertex from partA to every vertex from partB
        for(V u : partA){
            for(V w : partB){
                if(u == null || w == null){
                    continue;
                }
                if(!target.containsEdge(u, w)){
                    target.addEdge(u, w);
                }
            }
        }
    }catch(Exception ex){
