private int computeBinaryLog(int n) {
    // Compute floor(log2(n)) + 1, effectively the number of bits needed to represent n.
    // For n <= 0, the log is undefined; throw an exception to signal invalid input.
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer, got: " + n);
    }
    int bits = 0;
    int value = n;
    while (value > 0) {
        bits++;
        value >>>= 1; // unsigned right shift to prevent sign extension for negative numbers (not needed for positive but safe)
    }
    return bits;
}

