protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || tour.isEmpty() || graph == null) {
        return null;
    }
    try {
        // Copy of the edges to manipulate.
        Set<E> remaining = new HashSet<>(tour);
        List<E> orderedEdges = new ArrayList<>();

        // Choose an arbitrary starting edge.
        E startEdge = remaining.iterator().next();
        orderedEdges.add(startEdge);
        remaining.remove(startEdge);

        // Current vertex is the target of the last added edge.
        V currentVertex = graph.getEdgeTarget(startEdge);
        if (currentVertex == null) {
            return null;
        }

        // Build the path by following edges.
        while (!remaining.isEmpty()) {
            boolean found = false;
            Iterator<E> it = remaining.iterator();
            while (it.hasNext()) {
                E e = it.next();
                if (graph.getEdgeSource(e).equals(currentVertex)) {
                    orderedEdges.add(e);
                    currentVertex = graph.getEdgeTarget(e);
                    it.remove();
                    found = true;
                    break;
                }
            }
            if (!found) {
                // No forward continuation found; break to avoid infinite loop.
                break;
            }
        }

        // Compute total weight of the path.
        double totalWeight = 0.0;
        for (E e : orderedEdges) {
            totalWeight += graph.getEdgeWeight(e);
        }

        // Return a GraphPath instance.  If the JGraphT library is in use,
        // GraphPathImpl is a concrete implementation of GraphPath<V, E>.
        return new GraphPathImpl<>(graph, orderedEdges, totalWeight);
    } catch (Exception e) {
        // Any unexpected error results in a null path.
        return null;
    }
}

