    List<Integer> uniqueSorted = new ArrayList<>();
    Integer prev = null;
    for (Integer value : sorted) {
        if (!value.equals(prev)) {
            uniqueSorted.add(value);
            prev = value;
        }
    }
    // For each original key compute maximum lower bound
    for (Integer keyVal : intKeys) {
        if (keyVal == null || uniqueSorted.isEmpty()) {
            result.add(null);
            continue;
