private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        throw new IllegalArgumentException("Graph and vertex set must not be null");
    }

    int n = vertices.size();
    if (n <= 1) {
        return true; // empty or single vertex is trivially a clique
    }

    // Ensure all vertices belong to the graph
    for (V v : vertices) {
        if (!graph.containsVertex(v)) {
            throw new IllegalArgumentException("Vertex " + v + " is not part of the graph");
        }
    }

    // Check every unordered pair of vertices for adjacency
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1.equals(v2)) {
                continue;
            }
            // For undirected graphs, getEdge is sufficient
            if (graph.getEdge(v1, v2) == null) {
                return false; // missing edge means not a clique
            }
        }
    }
    return true;
}

