@SuppressWarnings("unchecked") public static void addToClassPath(Vector<URL> cpV,String dir){
    if (cpV == null || dir == null) {
        return;
    }
    try {
        File dirFile = new File(dir);
        if (!dirFile.exists() || !dirFile.isDirectory()) {
            return;
        }
        File[] jarFiles = dirFile.listFiles(new FilenameFilter() {
            @Override
            public boolean accept(File dir, String name) {
                return name.toLowerCase().endsWith(".jar") && new File(dir, name).isFile();
            }
        });
        if (jarFiles == null) {
            return;
        }
        for (File jar : jarFiles) {
            try {
                URL jarUrl = jar.toURI().toURL();
                if (!cpV.contains(jarUrl)) {
                    cpV.add(jarUrl);
                }
            } catch (MalformedURLException e) {
                // ignore malformed jar URLs
                System.err.println("Malformed jar URL skipped: " + jar + " (" + e.getMessage() + ")");
            }
        }
    } catch (Exception e) {
        // generic handling for unexpected errors
        System.err.println("Error adding jars to classpath: " + e.getMessage());
        e.printStackTrace();
    }
}

