public static String trimLeadingCharacter(String str, char leadingCharacter) {
    // Return the original string if it is null or empty
    if (str == null || str.isEmpty()) {
        return str;
    }

    int index = 0;
    int length = str.length();

    // Advance the index while the leading character matches
    while (index < length && str.charAt(index) == leadingCharacter) {
        index++;
    }

    // If all characters were trimmed, return an empty string
    if (index == length) {
        return "";
    }

    // Return the substring from the first non-leading character to the end
    return str.substring(index);
}

