public Logger exists(String name) {
    if (name == null) {
        throw new NullPointerException("Logger name cannot be null");
    }
    synchronized (this) {
        // First try to find the logger with the exact name
        Logger logger = this.loggerMap.get(name);
        if (logger != null) {
            return logger;
        }

        // If not found, walk up the hierarchy (dot separated)
        String currentName = name;
        int lastDot;
        while ((lastDot = currentName.lastIndexOf('.')) > 0) {
            currentName = currentName.substring(0, lastDot);
            logger = this.loggerMap.get(currentName);
            if (logger != null) {
                return logger;
            }
        }

        // Finally, check the root logger
        return this.rootLogger;
    }
}

