public static void createConfigurationDirectory(){
    try {
        String osName = System.getProperty("os.name");
        String userHome = System.getProperty("user.home");
        if (userHome == null || userHome.isEmpty()) {
            throw new RuntimeException("User home directory is not defined");
        }

        File dir;
        if (osName != null && osName.toLowerCase().contains("windows")
                && osName.toLowerCase().contains("2000")) {
            // On Windows 2000, create under the parent of user.home (typically "Documents and Settings")
            File parent = new File(userHome).getParentFile();
            if (parent == null || !parent.isDirectory()) {
                parent = new File(userHome);
            }
            dir = new File(parent, "lf5");
        } else {
            // On all other platforms, create under user.home
            dir = new File(userHome, "lf5");
        }

        if (!dir.exists() && !dir.mkdirs()) {
            throw new RuntimeException("Failed to create configuration directory: " + dir.getAbsolutePath());
        }
    } catch (SecurityException se) {
        throw new RuntimeException("Security manager prevented creation of configuration directory", se);
    }
}

