static long compressTimeBucket(long timeBucket,int dayStep){
    // Basic validations
    if(dayStep <= 0){
        throw new IllegalArgumentException("dayStep must be greater than zero");
    }
    if(timeBucket < 0){
        throw new IllegalArgumentException("timeBucket must be non-negative");
    }

    long yearLong = timeBucket / 10000;
    if(yearLong > Integer.MAX_VALUE){
        throw new IllegalArgumentException("year value out of range");
    }
    int year = (int) yearLong;
    int month = (int)((timeBucket / 100) % 100);
    int day   = (int)(timeBucket % 100);

    if(month < 1 || month > 12){
        throw new IllegalArgumentException("month out of range in timeBucket");
    }

    // Determine days in month (taking leap years into account)
    int daysInMonth;
    switch(month){
        case 1: case 3: case 5: case 7: case 8: case 10: case 12:
            daysInMonth = 31; break;
        case 4: case 6: case 9: case 11:
            daysInMonth = 30; break;
        case 2:
            boolean leap = (year % 4 == 0 && (year % 100 != 0 || year % 400 == 0));
            daysInMonth = leap ? 29 : 28;
            break;
        default:
            throw new IllegalArgumentException("invalid month value");
    }

    if(day < 1 || day > daysInMonth){
        throw new IllegalArgumentException("day out of range in timeBucket");
    }

    // Compute the start day of the compression bucket
    int startDay = ((day - 1) / dayStep) * dayStep + 1;
    // No need to adjust month/year because startDay will always be <= day <= daysInMonth

    return (long)year * 10000 + month * 100 + startDay;
}

