                if (i >= len){
                    throw new IllegalArgumentException("Invalid descriptor – missing type after array prefix");
                }
                char t = descriptor.charAt(i);
                if (t == 'L'){
                    int sem = descriptor.indexOf(';', i);
                    if (sem == -1){
                        throw new IllegalArgumentException("Object type not terminated with ';'");
                    }
                    i = sem + 1; // consume until ;
                }else if (t == 'V' || t == 'Z' || t == 'B' || t == 'C' ||
                          t == 'S' || t == 'I' || t == 'F' || t == 'J' || t == 'D'){
                    i++; // consume single bytecode type
                }else{
                    throw new IllegalArgumentException("Unknown descriptor character: " + t);
